package it.pagopa.posgw.common.documents

import java.time.Instant
import java.util.UUID
import org.springframework.data.annotation.Id
import org.springframework.data.mongodb.core.mapping.Document

/**
 * Base MongoDB document for an event recorded against a payment session.
 *
 * @param T type of the event-specific payload
 * @param id event identifier stored by MongoDB
 * @param timestamp time the event occurred
 * @param sessionId identifier of the session; a random UUID is generated by default
 * @param eventCode serialized event type
 * @param data event-specific payload
 */
@Document(collection = "eventstore")
abstract class BaseSessionEvent<T>(
    @Id val id: String,
    open val timestamp: Instant,
    open val sessionId: UUID = UUID.randomUUID(),
    open val eventCode: String,
    open val data: T
) {
    /**
     * Compares events by identifier, session, event code, and payload.
     *
     * The timestamp is not part of the equality comparison.
     *
     * @param other object to compare with this event
     * @return `true` if both references are identical or the compared fields are equal
     */
    final override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is BaseSessionEvent<*>) return false
        if (id != other.id) return false
        if (sessionId != other.sessionId) return false
        if (eventCode != other.eventCode) return false
        if (data != other.data) return false

        return true
    }

    /** Returns a hash code derived from the event identifier. */
    final override fun hashCode(): Int = id.hashCode()
}
